if(!exists('out')) source(file.path(dirname(normalizePath(gsub('~+~',' ',sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE)[1]),fixed=TRUE))),'common.R'))
suppressPackageStartupMessages(library(ggrepel))
st<-read_tsv(file.path(out,'tables/model_resolved_pathway_statistics.tsv'))
sel<-read_tsv(file.path(out,'tables/model_resolved_selected_pathways.tsv'))
programs<-read_tsv(file.path(out,'tables/model_resolved_pathway_comparison.tsv'))
groups<-c('Shared pathway support','Ovary-preferential candidates','tAge-preferential candidates')
plotdata<-merge(st,sel[,.(pathway_id,display_group,row_index)],by='pathway_id')
plotdata[,model:=factor(model,levels=models,labels=c('HVG\nElasticNet','VersionB\nPCA/glmnet','tAge\nscaled-diff','tAge\nYuGene-diff'))]
plotdata[,display_group:=factor(display_group,levels=groups)]
plotdata[,pathway_id:=factor(pathway_id,levels=rev(sel$pathway_id))]
write_tsv(plotdata,'tables/model_resolved_pathway_figure_source.tsv')
labels<-setNames(vapply(seq_len(nrow(sel)),function(i){z<-sub(' \\(GO:[0-9]+\\)$','',sel$pathway[i]);paste0(i,'. ',paste(strwrap(z,42),collapse='\n'))},character(1)),sel$pathway_id)
base<-theme_minimal(base_size=10)+theme(panel.grid=element_blank(),axis.text=element_text(color='black'),strip.text.y=element_text(angle=0,face='bold',size=9),plot.title=element_text(size=13,face='bold'),plot.subtitle=element_text(size=9),legend.position='bottom',panel.spacing.y=grid::unit(.5,'lines'))
effect_limit<-max(abs(plotdata[analysis=='absolute',rank_biserial]))
heat<-ggplot(plotdata[analysis=='absolute'],aes(model,pathway_id,fill=rank_biserial))+geom_tile(color='white',linewidth=.7)+geom_text(aes(label=ifelse(FDR<.05,'*','')),size=5)+scale_fill_gradient2(low='#527A9E',mid='white',high='#AB594C',midpoint=0,limits=c(-effect_limit,effect_limit),name='Pathway importance\n(rank-biserial effect)')+scale_y_discrete(labels=labels)+facet_grid(display_group~.,scales='free_y',space='free_y')+labs(title='a  Which clocks emphasize each pathway?',subtitle='Same rank-based effect for all clocks; * permutation BH FDR < 0.05',x=NULL,y=NULL)+base
sd<-copy(sel);sd[,`:=`(pathway_id=factor(pathway_id,levels=rev(sel$pathway_id)),display_group=factor(display_group,levels=groups))]
forest<-ggplot(sd,aes(difference,pathway_id))+geom_vline(xintercept=0,color='grey65',linetype='dashed')+geom_segment(aes(x=0,xend=difference,yend=pathway_id),linewidth=.8,color='grey70')+geom_point(aes(color=difference>0),size=2.5)+scale_color_manual(values=c('#538AA3','#B36874'),guide='none')+scale_y_discrete(labels=NULL)+facet_grid(display_group~.,scales='free_y',space='free_y')+labs(title='b  Relative pathway emphasis',subtitle='Difference of group means\nDescriptive; not a specificity test',x='tAge higher  <-  Difference  ->  Ovary higher',y=NULL)+base+theme(strip.text.y=element_blank(),axis.text.y=element_blank(),axis.title.x=element_text(size=9))
plot<-(heat+forest)+plot_layout(widths=c(3.3,1.65))+plot_annotation(title='Shared and preferential pathway weighting across frozen clocks',caption='Colour = pathway versus non-pathway weight-rank effect, not expression/activity. Means combine two algorithms per group.\nRepresentatives: >=15 mapped genes, effect-size ranking and Jaccard overlap <0.35. Preference does not establish tissue specificity.',theme=theme(plot.title=element_text(face='bold',size=15),plot.caption=element_text(size=9,hjust=0)))
savefig<-function(p,stem,w,h){ggsave(file.path(out,'figures',paste0(stem,'.pdf')),p,device=cairo_pdf,width=w,height=h);ggsave(file.path(out,'figures',paste0(stem,'.png')),p,device=ragg::agg_png,width=w,height=h,dpi=300,bg='white')}
savefig(plot,'pathway_model_resolved_comparison',15,10)
sg<-ggplot(plotdata[analysis=='signed'],aes(model,pathway_id,fill=rank_biserial))+geom_tile(color='white',linewidth=.7)+geom_text(aes(label=ifelse(FDR<.05,'*','')),size=5)+scale_fill_gradient2(low='#477AA6',mid='white',high='#B35E51',midpoint=0,breaks=c(-.5,0,.5),name='Signed weight-rank effect')+scale_y_discrete(labels=labels)+facet_grid(display_group~.,scales='free_y',space='free_y')+labs(title='Signed age-weight alignment of the same pathways',subtitle='Positive = pathway weights are shifted toward positive age coefficients; negative = toward negative coefficients',x=NULL,y=NULL,caption='* Two-sided gene-label permutation test, BH FDR <0.05 across all pathways per clock. Blank does not mean no biological effect.\nModel coefficients are conditional age associations, not pathway activation or measured age-related expression changes.')+base+theme(plot.caption=element_text(size=9,hjust=0))
savefig(sg,'pathway_signed_weight_alignment',12,10)
colours<-c('Shared support'='#65966C','Ovary support only'='#B36874','tAge support only'='#538AA3','No FDR support'='#C9CDD1')
global<-ggplot(programs[order(support_class!='No FDR support')],aes(tage_mean_effect,ovary_mean_effect,color=support_class))+geom_abline(slope=1,intercept=0,color='grey45',linetype='dashed')+geom_hline(yintercept=0,color='grey85')+geom_vline(xintercept=0,color='grey85')+geom_point(size=1,alpha=.65)+geom_point(data=sel,shape=21,fill='white',color='black',size=2.5)+geom_text_repel(data=sel,aes(label=row_index),seed=20261012,size=3,color='black',max.overlaps=Inf,min.segment.length=0)+scale_color_manual(values=colours)+coord_equal()+labs(title='All pathways: shared versus preferential model weighting',subtitle=sprintf('%s pathways; numbered representatives match the model-resolved figures',format(nrow(programs),big.mark=',')),x='Mean pathway importance in the two tAge variants',y='Mean pathway importance in the two ovary clocks',color='Individual-model FDR support',caption='Each point is a pathway; both axes use the same rank-biserial effect scale. The diagonal denotes equal group means.\nColours summarize at least one supported model per group. Read the four-model matrix before interpreting a group average.')+base+theme(plot.caption=element_text(size=9,hjust=0))
savefig(global,'pathway_all_programs_comparison',10,8)
